// Generated by GitHub Copilot - Oct-26-2026
const statusBadge = document.querySelector("#connection-status");
const statusLabel = document.querySelector("#status-label");
const resultTitle = document.querySelector("#result-title");
const resultDetail = document.querySelector("#result-detail");
const responseOutput = document.querySelector("#response-output");
const checkButton = document.querySelector("#check-button");
const catalogStatus = document.querySelector("#catalog-status");
const productList = document.querySelector("#product-list");

async function checkBackend() {
  checkButton.disabled = true;
  statusBadge.dataset.state = "checking";
  statusLabel.textContent = "Checking";
  resultTitle.textContent = "Connecting to backend";
  resultDetail.textContent = "Waiting for a response from the health endpoint.";
  responseOutput.textContent = "Request in progress...";
  try {
    const response = await fetch("http://127.0.0.1:3000/health", { headers: { Accept: "application/json" }, cache: "no-store", signal: AbortSignal.timeout(5000) });
    if (!response.ok) throw new Error("Backend returned an unsuccessful response");
    const payload = await response.json();
    if (payload.status !== "ok") throw new Error("Backend health response is invalid");
    statusBadge.dataset.state = "online";
    statusLabel.textContent = "Online";
    resultTitle.textContent = "Backend is responding";
    resultDetail.textContent = "The health check completed successfully.";
    responseOutput.textContent = JSON.stringify(payload, null, 2);
  } catch {
    statusBadge.dataset.state = "offline";
    statusLabel.textContent = "Offline";
    resultTitle.textContent = "Backend is unavailable";
    resultDetail.textContent = "Start the backend service and check again.";
    responseOutput.textContent = "No successful response received.";
  } finally { checkButton.disabled = false; }
}

/** Loads the product catalog and renders it in the frontend list. */
async function loadProducts() {
  catalogStatus.textContent = "Loading catalog...";
  productList.replaceChildren();
  try {
    const response = await fetch("http://127.0.0.1:3000/products", { headers: { Accept: "application/json" }, cache: "no-store" });
    if (!response.ok) throw new Error("Catalog request failed");
    const products = await response.json();
    if (!Array.isArray(products)) throw new Error("Invalid catalog");
    products.forEach((product) => {
      const item = document.createElement("li");
      item.textContent = `${product.name} · ${product.category} · €${Number(product.price).toFixed(2)} · ${product.available ? "Available" : "Unavailable"}`;
      productList.append(item);
    });
    catalogStatus.textContent = `${products.length} products loaded.`;
  } catch {
    catalogStatus.textContent = "Unable to load the catalog. Please try again later.";
  }
}

checkButton.addEventListener("click", checkBackend);
checkBackend();
loadProducts();
